#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // Size: empty stays empty; otherwise exactly 2n-1
        res.len() == if numbers.len() == 0 { 0 } else { 2 * numbers.len() - 1 },

        // Even indices are the original elements in order
        forall|k: int|
            0 <= k < numbers.len() ==> res[(2 * k) as int] == numbers[k],

        // Odd indices are the delimiter (between consecutive elements)
        forall|k: int|
            0 <= k < numbers.len() - 1 ==> res[(2 * k + 1) as int] == delim,
{
    let n = numbers.len();
    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            // res has exactly 2*i elements when i==0, else 2*i-1
            res.len() == if i == 0 { 0 } else { 2 * i - 1 },

            // All completed even positions match numbers
            forall|k: int|
                0 <= k < i as int ==> res[(2 * k) as int] == numbers[k],

            // All completed odd positions are delim (only for k < i-1)
            forall|k: int|
                0 <= k < i as int - 1 ==> res[(2 * k + 1) as int] == delim,
    {
        // Push the next original element
        res.push(numbers[i]);

        // If this is not the last element, push the delimiter after it
        if i + 1 < n {
            res.push(delim);
        }

        i += 1;
    }

    res
}

} // verus!